"""Shared helpers for DXT color decoding."""


def _decode_dxt_color(color_code, r0, g0, b0, r1, g1, b1):
    """Return the (r, g, b) color for a 2-bit DXT color code."""
    if color_code == 0:
        return r0, g0, b0
    elif color_code == 1:
        return r1, g1, b1
    elif color_code == 2:
        return (2 * r0 + r1) // 3, (2 * g0 + g1) // 3, (2 * b0 + b1) // 3
    elif color_code == 3:
        return (2 * r1 + r0) // 3, (2 * g1 + g0) // 3, (2 * b1 + b0) // 3
